class Bit:

	def __init__(self, n):
		self.n = n
		self.arr = [0] * (n + 1)

	def update(self, i, v):
		i += 1
		while i <= self.n:
			self.arr[i] += v
			i += i & -i

	def getsum(self, i):
		s = 0
		i = i + 1
		while i > 0:
			s += self.arr[i]
			i -= i & -i
		return s

	def print(self):
		print(self.arr)

