def dijkstraHeap(source, N, getAdj):
	from heapq import heappop, heappush
	inf = float('inf')
	dist = [inf] * N
	dist[source] = 0.0
	queue = [(0.0, float(source))]
	while queue:
		(d, u) = heappop(queue)
		u = int(u)
		if dist[u] == d:
			for (v, w) in getAdj(u):
				cost = d + w
				if cost < dist[v]:
					dist[v] = cost
					heappush(queue, (cost, float(v)))
	return dist

