def import_heapq(cmp_lt):
	import sys
	if sys.version_info < (3,):
		import heapq
		from heapq import heappush, heappop, _siftdown
		heapq.cmp_lt = cmp_lt
	else:

		def heappush(heap, item):
			heap.append(item)
			_siftdown(heap, 0, len(heap) - 1)

		def heappop(heap):
			lastelt = heap.pop()
			if heap:
				returnitem = heap[0]
				heap[0] = lastelt
				_siftup(heap, 0)
				return returnitem
			return lastelt

		def _siftdown(heap, startpos, pos):
			newitem = heap[pos]
			while pos > startpos:
				parentpos = pos - 1 >> 1
				parent = heap[parentpos]
				if cmp_lt(newitem, parent):
					heap[pos] = parent
					pos = parentpos
					continue
				break
			heap[pos] = newitem

		def _siftup(heap, pos):
			endpos = len(heap)
			startpos = pos
			newitem = heap[pos]
			childpos = 2 * pos + 1
			while childpos < endpos:
				rightpos = childpos + 1
				if rightpos < endpos and (not cmp_lt(heap[childpos], heap[rightpos])):
					childpos = rightpos
				heap[pos] = heap[childpos]
				pos = childpos
				childpos = 2 * pos + 1
			heap[pos] = newitem
			_siftdown(heap, startpos, pos)
	return (heappush, heappop, _siftdown)
