def binary_search(s_l, c):
	low = 0
	high = len(s_l) - 1
	while low <= high:
		mid = (low + high) // 2
		if s_l[mid] == c:
			return -1
		elif s_l[mid] > c:
			high = mid - 1
		else:
			low = mid + 1
	return low
