def prime_factors(n):
	pfs = set({})
	for p in possible_pfs:
		if n % p == 0:
			pfs.add(p)
			while n % p == 0:
				n //= p
		if p * p > n:
			break
	if n > 1:
		pfs.add(n)
	return pfs

def copr(l, r, x):
	if x:
		y = x.copy()
		p = y.pop()
		return copr(l, r, y) - copr(ceilq(l, p), r // p, y)
	else:
		return r - l + 1
