		length = deadline
	minLeft = minutes
	index = returnIndex(array, deadline - 1)
	if index != None:
		while index >= 0 and minLeft > 0:
			array.pop(index)
			index -= 1
			minLeft -= 1
	while minLeft > 0 and array and (array[0] < deadline):
		array.pop(0)
		minLeft -= 1
	late += minLeft
	return (late, length)
