MOD = 998244353

def mpow(x, k):
	ret = 1
	x %= MOD
	while k:
		if k & 1:
			ret = ret * x % MOD
		x = x * x % MOD
		k >>= 1
	return ret

def minv(x):
	return mpow(x, MOD - 2)

def mm(a, b):
	n = a.shape[0]
	ret = np.zeros(n, dtype=int)
	for i in range(n):
		ret += b[i] * a[:, i] % MOD
	return ret % MOD
