def gcd2(a, b):
	l = []
	while b:
		l.append(divmod(a, b))
		(a, b) = (b, a % b)
	(x, y) = (1, 0)
	for (aa, bb) in l[::-1]:
		(x, y) = (y, x - aa * y)
	return (a, x, y)

def modinv(x, M):
	(a, xx, yy) = gcd2(x, M)
	return (a, xx % M)

def solve(a, b, n):
	(g, xx, yy) = gcd2(a, n)
	if b % g != 0:
		return None
	a //= g
	n //= g
	b //= g
	ainv = modinv(a, n)[1]
	x = ainv * b % n
	return x

def crt(rs, ms):
	r0 = 0
	m0 = 1
	for (r1, m1) in zip(rs, ms):
		if m0 < m1:
			(m0, m1) = (m1, m0)
			(r0, r1) = (r1, r0)
		if m0 % m1 == 0:
			if r0 % m1 != r1:
				return (None, None)
			else:
				continue
		(g, im) = modinv(m0, m1)
		u1 = m1 // g
		if (r1 - r0) % g != 0:
			return (None, None)
		x = (r1 - r0) // g % u1 * im % u1
		r0 += x * m0
		m0 *= u1
		if r0 < 0:
			r0 += m0
	return (r0, m0)
