def solve(boxes):
	boxes.reverse()
	c = [0] * len(boxes)
	c[0] = dist(boxes[0][0], boxes[0][1])
	for bi in range(1, len(boxes)):
		(bx, by) = boxes[bi]
		cur_dist = dist(bx, by)
		dist_to_prev = dist(by, boxes[bi - 1][0])
		c[bi] = c[bi - 1] + dist_to_prev + cur_dist
		for i in range(0, bi - 1):
