def inorder(T):
	stack = [1]
	result = []
	while stack:
		i = stack.pop()
		if i > 0:
			if T[i][1] > 0:
				stack.append(T[i][1])
			stack.append(-i)
			if T[i][0] > 0:
				stack.append(T[i][0])
		else:
			result.append(-i)
	return result

def swap(T, K):
	(toVisit, depth) = ([1], 1)
	while toVisit:
		if depth % K == 0:
			for i in toVisit:
				T[i] = (T[i][1], T[i][0])
		toVisit_ = []
		for i in toVisit:
			if T[i][0] > 0:
				toVisit_.append(T[i][0])
			if T[i][1] > 0:
				toVisit_.append(T[i][1])
		toVisit = toVisit_
		depth += 1
