import bisect as bs
import heapq as hq

def force(cf, cm, f, m):
	return f * cf + m * cm

def mtable(sa):
	mt = [0] * len(sa)
	for i in range(1, len(sa)):
		mt[i] = mt[i - 1] + i * (sa[i] - sa[i - 1])
	return mt

def maxm(sa, mt, f, k):
	i = bs.bisect_right(mt, k, hi=len(sa) - f)
	return sa[i - 1] + (k - mt[i - 1]) // i

def optimize(a, amax, cf, cm, k):
	if sum(a) + k >= len(a) * amax:
		return (len(a) * cf + amax * cm, len(a), amax)
	sa = sorted(a)
	f = 0
	while sa[-f - 1] == amax:
		f += 1
	mt = mtable(sa)
	of = f
	om = maxm(sa, mt, f, k)
	o = force(cf, cm, of, om)
	while k >= amax - sa[-f - 1]:
		k -= amax - sa[-f - 1]
		f += 1
		m = maxm(sa, mt, f, k)
		t = force(cf, cm, f, m)
		if t > o:
			(of, om, o) = (f, m, t)
	return (o, of, om)

def apply(a, amax, of, om):
	a_ = [max(om, ai) for ai in a]
	h = [(-a[i], i) for i in range(len(a))]
	hq.heapify(h)
	for _ in range(of):
		(_, i) = hq.heappop(h)
		a_[i] = amax
	return a_

