class multiset:

	def __init__(self):
		self.items = dict()
		self.len = 0

	def add(self, it):
		self.items[it] = self.items.get(it, 0) + 1
		self.len += 1

	def remove(self, it):
		it_value = self.items.get(it, 1) - 1
		if it_value == 0:
			self.items.__delitem__(it)
		else:
			self.items[it] = it_value
		self.len -= 1

	def pop(self):
		it = next(iter(self.items.keys()))
		self.remove(it)
		return it

	def __len__(self):
		return self.len

	def __str__(self):
		return str(self.items)
