def search(field, m):
	if (field, m) in memo:
		return memo[field, m]
	white = m % 2 == 1
	for i in range(N):
		for j in range(N):
			f = field[i][j]
			if f == 0 or (f > 0) != white:
				continue
			for d in range(*RANGE[abs(f) - 1]):
				(dx, dy) = D[d]
				(x, y) = (i, j)
				while True:
					x += dx
					y += dy
					if x < 0 or x >= N or y < 0 or (y >= N):
						break
					g = field[x][y]
					if g != 0 and (g > 0) == (f > 0):
						break
					if abs(g) == 1:
						memo[field, m] = white
						return white
					if m > 1:
						new = list(map(list, field))
						new[i][j] = 0
						new[x][y] = f
						new = tuple(map(tuple, new))
						s = search(new, m - 1)
						if white == s:
							memo[field, m] = s
							return s
					if g:
						break
	memo[field, m] = not white
	return not white
